const el=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let token=sessionStorage.getItem('village-teacher-token')||'',data=null,editing=false;
async function request(url,body,auth=token){const r=await fetch(url,{method:body?'POST':'GET',headers:{'content-type':'application/json',...(auth?{authorization:'Bearer '+auth}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(15000)});const out=await r.json();if(!r.ok)throw Error(out.error||'처리하지 못했어요.');return out}
function csv(filename,rows){const text='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function show(d,force=false){data=d;el('#teacherLogin').hidden=true;el('#teacherDashboard').hidden=false;const r=d.room;el('#roomTitle').textContent='학급 '+r.code;el('#teacherSummary').innerHTML=`<span><b>${d.players.length}</b>전체 학생</span><span><b>${d.players.filter(p=>p.online).length}</b>최근 접속</span><span><b>${d.offers.length}</b>교환 제안</span><span><b>${r.coop.join(' / ')}</b>공동 식탁 · 각 ${r.goal}개 목표</span>`;if(force||!editing){el('#roomDay').value=r.day;el('#roomWeather').value=r.weather;el('#roomPhase').value=r.phase;el('#roomMarket').value=r.market?'1':'0';el('#roomPaused').value=r.paused?'1':'0'}el('#teacherRoster').innerHTML='<table><thead><tr><th>학생</th><th>연결</th><th>직업</th><th>수확</th><th>코인</th><th>상추/우유/사과/생선</th><th>기여</th></tr></thead><tbody>'+d.players.map(p=>`<tr><td>${esc(p.name)}<small style="display:block">${esc(p.accountName||'')}</small></td><td>${p.online?'접속 중':'대기'}</td><td>${['채소','낙농','과수','양식'][p.job]}</td><td>${p.picked}</td><td>${p.coins}</td><td>${p.stock.join(' / ')}</td><td>${p.donated.join(' / ')}</td></tr>`).join('')+'</tbody></table>'}
el('#joinTeacher').onclick=async()=>{try{const d=await request('/api/join',{roomCode:el('#teacherRoom').value,code:el('#teacherCode').value},'');if(!d.teacher)throw Error('교사 입장 코드를 사용해 주세요.');token=d.token;sessionStorage.setItem('village-teacher-token',token);show(d,true)}catch(e){el('#teacherError').textContent=e.message}};
el('#createClass').onclick=async()=>{const b=el('#createClass');b.disabled=true;try{const d=await request('/api/create',{setupKey:el('#setupKey').value,size:Number(el('#classSize').value)},'');el('#setupKey').value='';el('#newCodes').hidden=false;el('#newCodes').innerHTML=`<h2>학급 ${esc(d.roomCode)} 생성 완료</h2><p>교사 입장 코드를 별도로 보관하세요. 학생에게는 각자의 코드만 전달하세요.</p><div class="teacher-secret">${esc(d.teacherKey)}</div><button id="downloadStudentCodes" class="primary wide">학생 입장 코드 CSV 내려받기</button>`;el('#downloadStudentCodes').onclick=()=>csv(`학급-${d.roomCode}-학생코드.csv`,[['학급 코드','학생','입장 코드','역할'],...d.students.map(s=>[d.roomCode,s.name,s.code,['채소','낙농','과수','양식'][s.role]])]);token=d.teacherKey;sessionStorage.setItem('village-teacher-token',token);show(await request('/api/state'),true)}catch(e){el('#teacherError').textContent=e.message}finally{b.disabled=false}};
document.querySelectorAll('#roomDay,#roomWeather,#roomPhase,#roomMarket,#roomPaused').forEach(x=>x.onchange=()=>editing=true);
el('#saveRoom').onclick=async()=>{el('#saveRoom').disabled=true;try{const d=await request('/api/teacher',{day:Number(el('#roomDay').value),weather:Number(el('#roomWeather').value),phase:el('#roomPhase').value,market:el('#roomMarket').value==='1',paused:el('#roomPaused').value==='1'});editing=false;show(d,true);el('#teacherStatus').textContent='학급 전체에 적용했어요.'}catch(e){el('#teacherStatus').textContent=e.message}finally{el('#saveRoom').disabled=false}};
async function refresh(){if(!token)return;try{show(await request('/api/state'))}catch(e){el('#teacherStatus').textContent='연결 확인 필요: '+e.message}}el('#teacherRefresh').onclick=refresh;el('#teacherLogout').onclick=()=>{sessionStorage.removeItem('village-teacher-token');location.reload()};el('#exportProgress').onclick=()=>{if(!data)return;csv('학급-활동현황.csv',[['학생 번호','별명','직업','수확','코인','상추','우유','사과','생선','공동기여'],...data.players.map(p=>[p.accountName||p.name,p.name,['채소','낙농','과수','양식'][p.job],p.picked,p.coins,...p.stock,p.donated.reduce((a,b)=>a+b,0)])])};if(token)request('/api/state').then(d=>{if(!d.teacher)throw Error('교사 코드가 아닙니다.');show(d,true)}).catch(()=>{token='';sessionStorage.removeItem('village-teacher-token')});setInterval(()=>{if(!document.hidden)refresh()},10000);
